public class ExpeditionLogModuleView
extends AbstractBuildingModuleView {
    private boolean updated;
    private boolean unlocked;
    private ExpeditionLog log = new ExpeditionLog();

    @Override
    public void deserialize(@NotNull FriendlyByteBuf buf) {
        this.unlocked = buf.readBoolean();
        if (this.unlocked) {
            this.log.deserialize(buf);
        }
        this.updated = true;
    }

    public boolean checkAndResetUpdated() {
        boolean wasUpdated = this.updated;
        this.updated = false;
        return wasUpdated;
    }

    public ExpeditionLog getLog() {
        return this.log;
    }

    @Override
    public boolean isPageVisible() {
        return this.unlocked;
    }

    @Override
    @OnlyIn(value=Dist.CLIENT)
    public BOWindow getWindow() {
        return new ExpeditionLogModuleWindow(this);
    }

    @Override

