import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.core.colony.buildings.moduleviews.ItemListModuleView;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingFlorist;
import net.minecraft.client.Minecraft;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Player;

public class FloristFlowerListModuleView
extends ItemListModuleView {
    private static final int MAX_LEVEL_BEFORE_SORTING = 3;

    public FloristFlowerListModuleView() {
        super("flowers", (Component)Component.m_237115_((String)"com.minecolonies.gui.workerhuts.florist.flowers"), true, buildingView -> BuildingFlorist.getPlantablesForBuildingLevel(buildingView.getBuildingLevel()));
    }

    @Override
    public void removeItem(ItemStorage item) {
        if (this.buildingView.getBuildingLevel() <= 1) {
            MessageUtils.format("com.minecolonies.gui.workerhuts.florist.toolow", new Object[0]).sendTo(new Player[]{Minecraft.m_91087_().f_91074_});
            return;
        }
        super.removeItem(item);
    }

    @Override
    public void addItem(ItemStorage item) {
        if (this.buildingView.getBuildingLevel() <= 1) {
            MessageUtils.format("com.minecolonies.gui.workerhuts.florist.toolow", new Object[0]).sendTo(new Player[]{Minecraft.m_91087_().f_91074_});
            return;
        }
        int size = this.getSize();
        if (this.buildingView.getBuildingLevel() <= 3 && size >= 1) {
            MessageUtils.format("com.minecolonies.gui.workerhuts.florist.toomanybelow", new Object[0]).sendTo(new Player[]{Minecraft.m_91087_().f_91074_});
            return;
        }
        if (this.buildingView.getBuildingLevel() < 5 && size >= 5) {
            MessageUtils.format("com.minecolonies.gui.workerhuts.florist.toomany", new Object[0]).sendTo(new Player[]{Minecraft.m_91087_().f_91074_});
            return;
        }
        super.addItem(item);
    }
}

